class MinStack:
    """A stack that reports its smallest value."""

    def __init__(self):
        self._items = []
        self._mins = []

    def push(self, value):
        self._items.append(value)
        if not self._mins or value <= self._mins[-1]:
            self._mins.append(value)

    def pop(self):
        value = self._items.pop()
        if value == self._mins[-1]:
            self._mins.pop()
        return value

    def top(self):
        return self._items[-1]

    def get_min(self):
        if not self._mins:
            raise ValueError("min of empty stack")
        return self._mins[-1]

    def __len__(self):
        return len(self._items)
